{
"user_intent": "创建一个双耳支座零件，包含带 4 个安装孔的底板和两个带销孔的立耳板。",
"notes": "所有尺寸已从 mm 转换为 m。建模策略：1. 在上视基准面绘制底板外轮廓和 4 个安装孔，一次拉伸形成带孔底板；2. 在底板上表面绘制两个耳板的轮廓（含顶部半圆和中心销孔），一次拉伸形成两个耳板并贯穿销孔。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
{
"operation": "select_plane",
"description": "选择上视基准面作为草图平面（用于绘制底板）",
"params": {
"index": 1
}
},
{
"operation": "sketch_rectangle",
"description": "绘制底板外轮廓：80mm x 50mm，中心在原点",
"params": {
"x1": -0.04,
"y1": -0.025,
"x2": 0.04,
"y2": 0.025
}
},
{
"operation": "sketch_circles",
"description": "绘制 4 个直径 9mm 的安装孔，圆心位于 (±30mm, ±17mm)",
"params": {
"circles": [
{
"cx": 0.03,
"cy": 0.017,
"cz": 0,
"radius": 0.0045
},
{
"cx": -0.03,
"cy": 0.017,
"cz": 0,
"radius": 0.0045
},
{
"cx": 0.03,
"cy": -0.017,
"cz": 0,
"radius": 0.0045
},
{
"cx": -0.03,
"cy": -0.017,
"cz": 0,
"radius": 0.0045
}
]
}
},
{
"operation": "feature_extrusion",
"description": "拉伸底板，厚度 10mm。由于在上视面绘图，默认沿 +Y 方向拉伸",
"params": {
"depth": 0.01
}
},
{
"operation": "select_face_and_sketch",
"description": "选中底板上表面进入草图编辑（用于绘制耳板）",
"params": {
"rx": 0,
"ry": 0.011,
"rz": 0,
"dx": 0,
"dy": -1,
"dz": 0
}
},
{
"operation": "sketch_rectangle",
"description": "绘制左耳板矩形部分：宽 30mm (Z 向), 高 25mm (Y 向)。中心 X=-0.025 (距原点 25mm), Z=0。矩形左下角 (-0.025, 0.01, -0.015), 右上角 (-0.025, 0.035, 0.015)",
"params": {
"x1": -0.025,
"y1": 0.01,
"z1": -0.015,
"x2": -0.025,
"y2": 0.035,
"z2": 0.015
}
},
{
"operation": "sketch_arc",
"description": "绘制左耳板顶部半圆：圆心 (-0.025, 0.035, 0), 半径 15mm, 从右侧点逆时针画到左侧点",
"params": {
"cx": -0.025,
"cy": 0.035,
"cz": 0,
"startX": -0.025,
"startY": 0.035,
"startZ": 0.015,
"endX": -0.025,
"endY": 0.035,
"endZ": -0.015,
"direction": -1
}
},
{
"operation": "sketch_circle",
"description": "绘制左耳板中心的销孔：直径 12mm, 圆心 (-0.025, 0.035, 0)",
"params": {
"cx": -0.025,
"cy": 0.035,
"cz": 0,
"radius": 0.006
}
},
{
"operation": "sketch_rectangle",
"description": "绘制右耳板矩形部分：宽 30mm (Z 向), 高 25mm (Y 向)。中心 X=+0.025, Z=0。矩形左下角 (0.025, 0.01, -0.015), 右上角 (0.025, 0.035, 0.015)",
"params": {
"x1": 0.025,
"y1": 0.01,
"z1": -0.015,
"x2": 0.025,
"y2": 0.035,
"z2": 0.015
}
},
{
"operation": "sketch_arc",
"description": "绘制右耳板顶部半圆：圆心 (0.025, 0.035, 0), 半径 15mm, 从右侧点逆时针画到左侧点",
"params": {
"cx": 0.025,
"cy": 0.035,
"cz": 0,
"startX": 0.025,
"startY": 0.035,
"startZ": 0.015,
"endX": 0.025,
"endY": 0.035,
"endZ": -0.015,
"direction": -1
}
},
{
"operation": "sketch_circle",
"description": "绘制右耳板中心的销孔：直径 12mm, 圆心 (0.025, 0.035, 0)",
"params": {
"cx": 0.025,
"cy": 0.035,
"cz": 0,
"radius": 0.006
}
},
{
"operation": "feature_extrusion",
"description": "拉伸两个耳板轮廓并切除销孔。由于耳板沿 80mm 方向 (X 轴) 延伸，需设置拉伸深度为 10mm 并使用中间面拉伸，使耳板关于草图面对称分布",
"params": {
"depth": 0.01,
"midPlane": true
}
}
]
}

{
"user_intent": "创建一个菱形法兰座零件，包含特定轮廓的法兰板、两个安装孔、一个中心凸台和一个贯穿中心孔。",
"notes": "1. 所有尺寸已从 mm 转换为米。2. 法兰轮廓由三个共线圆心（中心 R25，两侧距中心 42mm 处各 R12）及公切线构成，需计算切点坐标绘制封闭草图。3. 采用先画外轮廓和孔，一次拉伸成型法兰板，再在顶面画凸台并拉伸的策略。4. 中心孔使用'完全贯穿'条件。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
{
"operation": "select_plane",
"description": "选择前视基准面作为草图平面",
"params": {
"index": 0
}
},
{
"operation": "sketch_circle",
"description": "绘制中心大圆弧 (R25mm)",
"params": {
"cx": 0.0,
"cy": 0.0,
"radius": 0.025
}
},
{
"operation": "sketch_circle",
"description": "绘制左侧小圆弧 (R12mm, 圆心 X=-42mm)",
"params": {
"cx": -0.042,
"cy": 0.0,
"radius": 0.012
}
},
{
"operation": "sketch_circle",
"description": "绘制右侧小圆弧 (R12mm, 圆心 X=+42mm)",
"params": {
"cx": 0.042,
"cy": 0.0,
"radius": 0.012
}
},
{
"operation": "sketch_line",
"description": "绘制上方公切线 (连接左圆上切点和右圆上切点)",
"params": {
"x1": -0.042,
"y1": 0.012,
"x2": 0.042,
"y2": 0.012
}
},
{
"operation": "sketch_line",
"description": "绘制下方公切线 (连接左圆下切点和右圆下切点)",
"params": {
"x1": -0.042,
"y1": -0.012,
"x2": 0.042,
"y2": -0.012
}
},
{
"operation": "sketch_circle",
"description": "绘制左侧安装孔 (直径 10mm)",
"params": {
"cx": -0.042,
"cy": 0.0,
"radius": 0.005
}
},
{
"operation": "sketch_circle",
"description": "绘制右侧安装孔 (直径 10mm)",
"params": {
"cx": 0.042,
"cy": 0.0,
"radius": 0.005
}
},
{
"operation": "sketch_circle",
"description": "绘制中心通孔 (直径 20mm)",
"params": {
"cx": 0.0,
"cy": 0.0,
"radius": 0.01
}
},
{
"operation": "feature_extrusion",
"description": "拉伸法兰板主体 (深度 8mm)，同时生成安装孔和中心孔",
"params": {
"depth": 0.008
}
},
{
"operation": "select_face_and_sketch",
"description": "选中法兰板上表面进入草图模式以绘制凸台",
"params": {
"rx": 0.0,
"ry": 0.01,
"rz": 0.0,
"dx": 0.0,
"dy": -1.0,
"dz": 0.0
}
},
{
"operation": "sketch_circle",
"description": "绘制凸台轮廓 (直径 34mm)",
"params": {
"cx": 0.0,
"cy": 0.0,
"cz": 0.008,
"radius": 0.017
}
},
{
"operation": "feature_extrusion",
"description": "拉伸凸台 (高度 18mm，使总高达到 26mm)",
"params": {
"depth": 0.018
}
}
]
}

{
"user_intent": "创建一个轴支撑座零件，包含带半圆顶的立板和底座，立板上有轴孔，底座上有两个安装孔，所有结构合并为单一实体。",
"notes": "单位换算：100mm=0.1m, 50mm=0.05m, 10mm=0.01m, 20mm=0.02m, 24mm=0.024m (半径 0.012m), 10mm=0.01m (半径 0.005m), 38mm=0.038m, 40mm=0.04m。建模策略：在前视基准面绘制整体轮廓（底座矩形 + 立板矩形 + 顶部半圆弧 + 轴孔圆 + 底座安装孔圆），利用同心圆自动挖孔原理，一次拉伸生成带孔的单一实体。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
{
"operation": "select_plane",
"description": "选择前视基准面（X-Y 平面）作为草图平面，Z 轴为拉伸方向",
"params": {
"index": 0
}
},
{
"operation": "sketch_rectangle",
"description": "绘制底座轮廓：宽 100mm (X 方向), 高 10mm (Y 方向)，中心在 (0, 0.005)",
"params": {
"x1": -0.05,
"y1": 0.0,
"x2": 0.05,
"y2": 0.01
}
},
{
"operation": "sketch_rectangle",
"description": "绘制立板下部矩形轮廓：宽 50mm (X 方向), 高 15mm (Y 方向，从底座顶面 Y=0.01 到 Y=0.025)，中心在 (0, 0.0175)",
"params": {
"x1": -0.025,
"y1": 0.01,
"x2": 0.025,
"y2": 0.025
}
},
{
"operation": "sketch_arc",
"description": "绘制立板顶部半圆：圆心 (0, 0.04), 半径 25mm，起点 (-0.025, 0.025)，终点 (0.025, 0.025)，逆时针方向",
"params": {
"cx": 0.0,
"cy": 0.04,
"startX": -0.025,
"startY": 0.025,
"endX": 0.025,
"endY": 0.025,
"direction": -1
}
},
{
"operation": "sketch_circle",
"description": "绘制轴孔轮廓：圆心 (0, 0.04)，直径 24mm (半径 0.012m)。此圆与外部轮廓嵌套，拉伸时将自动形成通孔",
"params": {
"cx": 0.0,
"cy": 0.04,
"radius": 0.012
}
},
{
"operation": "sketch_circle",
"description": "绘制左侧底座安装孔：圆心 (-0.038, 0.005)（距中心 38mm，高度居中），直径 10mm (半径 0.005m)",
"params": {
"cx": -0.038,
"cy": 0.005,
"radius": 0.005
}
},
{
"operation": "sketch_circle",
"description": "绘制右侧底座安装孔：圆心 (0.038, 0.005)，直径 10mm (半径 0.005m)",
"params": {
"cx": 0.038,
"cy": 0.005,
"radius": 0.005
}
},
{
"operation": "feature_extrusion",
"description": "拉伸所有轮廓生成单一实体：深度 20mm (立板厚度)。外轮廓凸起，内圈（轴孔和安装孔）自动切除形成贯穿孔",
"params": {
"depth": 0.02
}
}
]
}

{
"user_intent": "创建一个轴支撑座零件，包含带半圆顶的立板和底座，立板上有轴孔，底座上有两个安装孔，所有结构合并为单一实体。",
"notes": "单位换算：100mm=0.1m, 50mm=0.05m, 10mm=0.01m, 20mm=0.02m, 24mm=0.024m (半径 0.012m), 10mm=0.01m (半径 0.005m)。建模策略：先画底座矩形和两个安装孔圆在同一草图并拉伸；然后在底座上表面画立板轮廓（矩形 + 半圆）和轴孔圆在同一草图并拉伸，利用 SolidWorks 多实体自动合并或接触合并特性确保单一实体。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
{
"operation": "select_plane",
"description": "选择上视基准面绘制底座草图",
"params": {
"index": 1
}
},
{
"operation": "sketch_rectangle",
"description": "绘制底座外轮廓 100x50mm，中心在原点",
"params": {
"x1": -0.05,
"y1": -0.025,
"x2": 0.05,
"y2": 0.025
}
},
{
"operation": "sketch_circle",
"description": "绘制左侧安装孔，直径 10mm，中心距原点 38mm",
"params": {
"cx": -0.038,
"cy": 0,
"radius": 0.005
}
},
{
"operation": "sketch_circle",
"description": "绘制右侧安装孔，直径 10mm，中心距原点 38mm",
"params": {
"cx": 0.038,
"cy": 0,
"radius": 0.005
}
},
{
"operation": "feature_extrusion",
"description": "拉伸底座厚度 10mm",
"params": {
"depth": 0.01
}
},
{
"operation": "select_face_and_sketch",
"description": "选中底座上表面进入草图编辑",
"params": {
"rx": 0,
"ry": 0.011,
"rz": 0,
"dx": 0,
"dy": -1,
"dz": 0
}
},
{
"operation": "sketch_rectangle",
"description": "绘制立板下部矩形轮廓：宽 50mm (X 方向)，高从底面到半圆起点 (40-25=15mm)",
"params": {
"x1": -0.025,
"y1": 0,
"x2": 0.025,
"y2": 0.015
}
},
{
"operation": "sketch_arc",
"description": "绘制立板顶部半圆：圆心 (0, 0.040)，半径 25mm，从左端点到右端点逆时针",
"params": {
"cx": 0,
"cy": 0.04,
"startX": -0.025,
"startY": 0.04,
"endX": 0.025,
"endY": 0.04,
"direction": -1
}
},
{
"operation": "sketch_circle",
"description": "绘制轴孔，直径 24mm，圆心与半圆圆心重合",
"params": {
"cx": 0,
"cy": 0.04,
"radius": 0.012
}
},
{
"operation": "feature_extrusion",
"description": "拉伸立板及轴孔，深度 20mm (轴孔自动贯穿立板)",
"params": {
"depth": 0.02
}
}
]
}

{
"user_intent": "创建一个单一实体的曲柄零件，包含带轴孔的圆柱轮毂、由两段圆弧和公切线组成的曲柄臂，以及带贯穿孔的曲柄销座。",
"notes": "所有尺寸已从 mm 转换为 m。建模策略：1. 在前视基准面绘制轮毂外圆、轴孔、曲柄臂轮廓（两圆弧 + 公切线）及销座孔的投影圆，一次性拉伸形成基础实体（利用同心圆自动挖孔，利用多轮廓拉伸合并实体）。2. 在顶面绘制销座凸台并拉伸。3. 对销座孔进行贯穿切除。此方法确保所有部分合并为单一实体。注意：R18 和 R11 圆弧的公切线需要通过几何计算确定切点坐标。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
{
"operation": "select_plane",
"description": "选择前视基准面进入草图编辑",
"params": {
"index": 0
}
},
{
"operation": "sketch_circle",
"description": "绘制轮毂外圆 (直径 36mm, 半径 18mm)",
"params": {
"cx": 0.0,
"cy": 0.0,
"radius": 0.018
}
},
{
"operation": "sketch_circle",
"description": "绘制轮毂中心轴孔 (直径 16mm, 半径 8mm)",
"params": {
"cx": 0.0,
"cy": 0.0,
"radius": 0.008
}
},
{
"operation": "sketch_circle",
"description": "绘制曲柄臂外侧大圆弧轮廓 (R18mm, 圆心在原点)",
"params": {
"cx": 0.0,
"cy": 0.0,
"radius": 0.018
}
},
{
"operation": "sketch_circle",
"description": "绘制曲柄臂端部小圆弧轮廓 (R11mm, 圆心在 Y=60mm 处)",
"params": {
"cx": 0.0,
"cy": 0.06,
"radius": 0.011
}
},
{
"operation": "sketch_circle",
"description": "绘制销座中心孔轮廓 (直径 10mm, 半径 5mm, 圆心在 Y=60mm)",
"params": {
"cx": 0.0,
"cy": 0.06,
"radius": 0.005
}
},
{
"operation": "sketch_line",
"description": "绘制右侧公切线 (连接 R18 和 R11 圆弧的右切点)",
"params": {
"x1": 0.0147,
"y1": 0.0103,
"x2": 0.0091,
"y2": 0.0662
}
},
{
"operation": "sketch_line",
"description": "绘制左侧公切线 (连接 R18 和 R11 圆弧的左切点)",
"params": {
"x1": -0.0147,
"y1": 0.0103,
"x2": -0.0091,
"y2": 0.0662
}
},
{
"operation": "feature_extrusion",
"description": "拉伸草图形成轮毂和曲柄臂基础实体 (深度 10mm)。同心圆自动形成轴孔，多轮廓合并为单一实体。",
"params": {
"depth": 0.01
}
},
{
"operation": "select_face_and_sketch",
"description": "选中曲柄臂上表面 (Y=0.01 平面附近) 准备绘制销座",
"params": {
"rx": 0.0,
"ry": 0.02,
"rz": 0.0,
"dx": 0.0,
"dy": -1.0,
"dz": 0.0
}
},
{
"operation": "sketch_circle",
"description": "在臂端面绘制销座外圆 (直径 22mm, 半径 11mm)",
"params": {
"cx": 0.0,
"cy": 0.0,
"cz": 0.06,
"radius": 0.011
}
},
{
"operation": "feature_extrusion",
"description": "拉伸销座凸台 (高度 15mm)",
"params": {
"depth": 0.015
}
},
{
"operation": "select_face_and_sketch",
"description": "选中销座顶面准备绘制贯穿孔",
"params": {
"rx": 0.0,
"ry": 0.035,
"rz": 0.06,
"dx": 0.0,
"dy": -1.0,
"dz": 0.0
}
},
{
"operation": "sketch_circle",
"description": "绘制销座中心孔 (直径 10mm, 半径 5mm)",
"params": {
"cx": 0.0,
"cy": 0.0,
"cz": 0.06,
"radius": 0.005
}
},
{
"operation": "feature_cut_extrusion",
"description": "切除销座孔，贯穿整个零件",
"params": {
"depth": 0.05,
"endCondition": "through_all"
}
}
]
}

